/**
 * Uncheck other checkboxes
 *
 * Find any other checkbox inputs with the checkbox group value, and uncheck them.
 * This is useful for when a “None of these” checkbox is checked.
 *
 * @param {HTMLInputElement} $input - Checkbox input
 */
unCheckAllInputsExcept($input) {
  const { checkboxExclusiveGroup: exclusiveGroup } = $input.dataset

  let inputs
  if (exclusiveGroup) {
    inputs = document.querySelectorAll(
      `input[type="checkbox"][data-checkbox-exclusive-group="${exclusiveGroup}"]`
    )
  } else {
    inputs = document.querySelectorAll(
      `input[type="checkbox"][name="${$input.name}"]`
    )
  }

  inputs.forEach(($otherInput) => {
    const hasSameFormOwner = $input.form === $otherInput.form

    if (hasSameFormOwner && $otherInput !== $input) {
      this.setInputState($otherInput, false, exclusiveGroup)
    }
  })
}
